	<script>
  function velocitySuccessCallback(msg) {
       console.log("welcome success",msg);
       
      var card_num= $('#PAN').val();
      var card_num= $('#PAN').val();
      var expiry=$('#Expire').val();
      var cvv=$('#CVV').val();
      var amount=$('#Amount').val();
      var user_id=$('#userId').val();
      var no_of_licenses=$('#noOfLicenses').val();
      var no_of_packages=$('#noOfPackages').val();
      var extra_licenses=$('#extraLicenses').val();
      var package_choice=$('#packageChoice').val();
      var subscription_type=$('#subscriptionType').val();
      
      console.log("card_num",card_num,"exp",expiry,"cvv",cvv,"amoount",amount,"userID",user_id,"nooflcenses",no_of_licenses,"no of packages",no_of_packages,"extra licenses",extra_licenses,"Subscription",subscription_type,"packageChoice",package_choice);
      $.ajax({

    url : '{{ url('/api/update-billing') }}', headers : {'Authorization': 'Bearer ' + window.localStorage.getItem('accessToken')},
    type : 'POST',
    data : {
        'card_num' : card_num,
        'expiry':expiry,
        'cvv':cvv,
        'amount':amount,
        'user_id':user_id,
        'no_of_licenses':no_of_licenses,
        'extra_licenses':extra_licenses,
        'subscription_type':subscription_type,
        'package_choice':package_choice,
        'no_of_packages':no_of_packages,
    },
    dataType:'json',
    success : function(dataType) {              
        Swal.fire({
                  position: 'center',
                  icon: 'success',
                  title: 'Payment successful!',
                  showConfirmButton: false,
                  timer: 1500
                });
            //console.log('user',dataType.user);
                                 let appState = {
                     isLoggedIn: true,
                     user: dataType.user
                  };
                  localStorage["appState"] = JSON.stringify(appState);
              
               window.location.replace("/dashboard");

//          this.props.history.push('')
          
    },
    error : function(request,error)
    {
        
    }
});
    // alert('Success: ' + msg);
  }
  function velocityFailureCallback(msg){
    console.log("failuer",msg);
    Swal.fire({
                  position: 'center',
                  icon: 'error',
                  title: 'Payment unsuccessful!',
                  showConfirmButton: true,
                });
  }
</script>
